      {error && <Failure error={error} />}
      <Label for="sign-in-user" required>Email or username</Label><Input id="sign-in-user" accessibleName="Email or username" name="username" value={username} disabled={busy} onInput={event => setUsername(event.currentTarget!.value)} />
      <Label for="sign-in-password" required>Password</Label><Input id="sign-in-password" accessibleName="Password" type="Password" name="password" value={password} disabled={busy} onInput={event => setPassword(event.currentTarget!.value)} />
      <Button design="Emphasized" type="Submit" disabled={busy || !username.trim() || !password}>{busy ? 'Signing in…' : 'Sign in'}</Button>
    </form><div className="sign-in-footnote"><Icon name="locked" /><span>Your account controls access to companies, projects and documents.</span></div>
  </section></div>;
}

import { ApiError, rpc } from './client';
import type { EstEstimateRecord, EstRateRecord, EstAssemblyRecord, EstConversionRecord, EstRevisionRecord, EstSnapshotRecord, EstLineRecord, EstListResponse, ListEstimateUnitsResponse, CreateEstimateRequest, CreateEstimateResponse, CalculateRevisionRequest, CalculateRevisionResponse } from './estimating.generated';

export interface EstimateRecords { estimate: EstEstimateRecord; rate: EstRateRecord; assembly: EstAssemblyRecord; conversion: EstConversionRecord; revision: EstRevisionRecord; snapshot: EstSnapshotRecord; line: EstLineRecord }
const prefix = 'cipher_aec.estimating.api.';
export const estimating = {
  list: <K extends 'estimate' | 'rate' | 'assembly' | 'conversion'>(company: string, project: string, kind: K, signal?: AbortSignal, cursor?: string) => rpc<Omit<EstListResponse, 'items'> & { items: EstimateRecords[K][] }>(`${prefix}list_records`, { company, project, kind, limit: 50, count_mode: 'exact', cursor }, false, signal),
  get: <K extends keyof EstimateRecords>(company: string, project: string, kind: K, record_id: string, signal?: AbortSignal) => rpc<EstimateRecords[K]>(`${prefix}get_record`, { company, project, kind, record_id }, false, signal),
  units: (company: string, project: string, signal?: AbortSignal) => rpc<ListEstimateUnitsResponse>(`${prefix}list_units`, { company, project }, false, signal),
  create: (input: CreateEstimateRequest & { operation_id: string }) => rpc<CreateEstimateResponse>(`${prefix}create_estimate`, { ...input }, true),
  calculate: (input: CalculateRevisionRequest & { operation_id: string }) => rpc<CalculateRevisionResponse>(`${prefix}calculate_revision`, { ...input }, true),
};

export async function loadEstimate(company: string, project: string, id: string, signal: AbortSignal, revisionId?: string) {
  const estimate = await estimating.get(company, project, 'estimate', id, signal);
  const selected = revisionId || estimate.current_revision;
  if (!selected) return { estimate };
  const revision = await estimating.get(company, project, 'revision', selected, signal);
  if (revision.estimate !== estimate.id) throw new ApiError('This revision is unavailable for this estimate.', 'REVISION_UNAVAILABLE', 404);
  const snapshot = await estimating.get(company, project, 'snapshot', revision.calculation_snapshot, signal);
  if (snapshot.subject_id !== revision.id) throw new ApiError('This calculation is unavailable for this revision.', 'SNAPSHOT_UNAVAILABLE', 404);
  return { estimate, revision, snapshot };
}
export type EstimateView = Awaited<ReturnType<typeof loadEstimate>>;

import type { EstAdjustment, EstAssemblyDefinition, EstLineInput, EstRateDefinition, EstSnapshotRecord, EstUnitRecord } from './api/estimating.generated';

export interface EstimateDraft { lines: EstLineInput[]; adjustments: EstAdjustment[]; conversion_ids: string[]; basis_description: string; basis_citations: EstSnapshotRecord['inputs']['basis_citations'] }
export interface SourceChoice { id: string; kind: 'rate' | 'assembly'; label: string; unitId: string; rate?: EstRateDefinition; assembly?: EstAssemblyDefinition }
export const decimalPattern = /^(0|[1-9][0-9]*)(\.[0-9]{1,12})?$/;
export function exactDisplay(value: string) {
  const [integer, fraction] = value.split('.');
  return `${integer.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}${fraction === undefined ? '' : `.${fraction}`}`;
}
export function emptyLine(unit?: EstUnitRecord, source?: SourceChoice): EstLineInput {
  const base = { line_id: crypto.randomUUID(), description: '', quantity: { amount: '', unit_id: unit?.id ?? '', precision: unit?.fields.precision ?? 0 }, cost_code: '', notes: '', alternate: '', included: true };
  return source?.kind === 'assembly' ? { ...base, assembly_revision_id: source.id } : { ...base, rate_source_id: source?.id ?? '', material_factor: '1', waste_fraction: '0' };
}
export function selectLineSource(line: EstLineInput, source: SourceChoice): EstLineInput {
  const { line_id, description, quantity, cost_code, notes, alternate, included } = line;
  const base = { line_id, description, quantity, cost_code, notes, alternate, included };
  return source.kind === 'assembly' ? { ...base, assembly_revision_id: source.id } : { ...base, rate_source_id: source.id, material_factor: 'material_factor' in line ? line.material_factor : '1', waste_fraction: 'waste_fraction' in line ? line.waste_fraction : '0' };
}
export function validateDraft(draft: EstimateDraft, units: EstUnitRecord[], choices: SourceChoice[]) {
  const errors: Record<string, string> = {};
  if (!draft.lines.length || draft.lines.length > 100) errors.lines = 'Use 1–100 estimate lines.';
  if (!draft.basis_description.trim()) errors.basis_description = 'Describe the basis of this authored estimate.';
  for (const [index, line] of draft.lines.entries()) {
    const key = `lines.${index}`;
    const unit = units.find(item => item.id === line.quantity.unit_id);
    if (!line.description.trim()) errors[`${key}.description`] = 'Enter a description.';
    if (!decimalPattern.test(line.quantity.amount) || line.quantity.amount.length > 43) errors[`${key}.quantity`] = 'Use an exact nonnegative decimal, without commas or exponent notation.';
    else if (unit && (line.quantity.amount.split('.')[1]?.length ?? 0) > unit.fields.precision) errors[`${key}.quantity`] = `This unit permits ${unit.fields.precision} decimal places.`;
    if (!unit) errors[`${key}.unit`] = 'Choose a qualified unit.';
    const sourceId = 'rate_source_id' in line ? line.rate_source_id : line.assembly_revision_id;
    if (!choices.some(source => source.id === sourceId)) errors[`${key}.source`] = 'Choose a current rate or assembly source.';
    if ('material_factor' in line) {
      if (!decimalPattern.test(line.material_factor) || !/[1-9]/.test(line.material_factor)) errors[`${key}.material_factor`] = 'Use an exact positive decimal.';
      if (!decimalPattern.test(line.waste_fraction)) errors[`${key}.waste_fraction`] = 'Use an exact nonnegative fraction; 0.05 means 5%.';
    }
  }
  draft.adjustments.forEach((adjustment, index) => {
    if (!decimalPattern.test(adjustment.value) || !adjustment.label.trim() || !adjustment.basis_description.trim()) errors[`adjustments.${index}`] = 'Each adjustment needs a label, an exact nonnegative value, and its basis.';
  });
  return errors;
}
export function parsePastedLines(text: string, units: EstUnitRecord[], choices: SourceChoice[]) {
  const rows = text.trim().split(/\r?\n/).filter(row => row.trim());
  if (rows[0]?.split('\t')[0].toLowerCase() === 'description') rows.shift();
  if (!rows.length || rows.length > 100) throw new Error('Paste 1–100 tab-separated rows.');
  const lines = rows.map((row, index) => {
    const [description = '', amount = '', symbol = '', sourceToken = '', costCode = '', waste = '0', ...extra] = row.split('\t');
    if (extra.length) throw new Error(`Row ${index + 1}: use the six supported columns.`);
    const matches = units.filter(unit => unit.id === symbol || unit.fields.symbol === symbol || unit.target.name === symbol);
    if (matches.length !== 1) throw new Error(`Row ${index + 1}: choose one exact qualified unit name or ID.`);
    const sources = choices.filter(source => source.id === sourceToken || source.label === sourceToken || source.rate?.title === sourceToken || source.assembly?.title === sourceToken);
    if (sources.length !== 1) throw new Error(`Row ${index + 1}: choose one exact source title or ID.`);
    const line = { ...emptyLine(matches[0], sources[0]), description, cost_code: costCode, quantity: { amount, unit_id: matches[0].id, precision: matches[0].fields.precision } };
    return 'waste_fraction' in line ? { ...line, waste_fraction: waste } : line;
  });
  const errors = validateDraft({ lines, adjustments: [], conversion_ids: [], basis_description: 'Pasted authored quantities', basis_citations: [] }, units, choices);
  if (Object.keys(errors).length) throw new Error(Object.values(errors)[0]);
  return lines;
}
export function draftFromSnapshot(snapshot?: EstSnapshotRecord): EstimateDraft {
  return snapshot ? structuredClone({ lines: snapshot.inputs.lines, adjustments: snapshot.inputs.adjustments, conversion_ids: snapshot.inputs.unit_manifest.unit_conversions.map(conversion => conversion.id), basis_description: snapshot.inputs.basis_description, basis_citations: snapshot.inputs.basis_citations }) : { lines: [], adjustments: [], conversion_ids: [], basis_description: '', basis_citations: [] };
}

import { useState } from 'react';
import { Bar, Button, CheckBox, Dialog, Input, Label, MessageStrip, Option, Select, Table, TableCell, TableHeaderCell, TableHeaderRow, TableRow, TextArea, Title, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import type { EstLineInput, EstUnitRecord, EstCalculatedLine } from './api/estimating.generated';
import { emptyLine, exactDisplay, parsePastedLines, selectLineSource, type EstimateDraft, type SourceChoice } from './estimate-editing';

export default function EstimateLineEditor({ draft, units, choices, calculated, errors, disabled, onChange, onInspect }: { draft: EstimateDraft; units: EstUnitRecord[]; choices: SourceChoice[]; calculated: EstCalculatedLine[]; errors: Record<string, string>; disabled: boolean; onChange: (draft: EstimateDraft) => void; onInspect: (kind: 'rate' | 'assembly', id: string) => void }) {
  const [pasteOpen, setPasteOpen] = useState(false);
  const [detailId, setDetailId] = useState<string>();
  const setLine = (index: number, line: EstLineInput) => onChange({ ...draft, lines: draft.lines.map((value, row) => row === index ? line : value) });
  const detailIndex = draft.lines.findIndex(line => line.line_id === detailId);
  const detail = draft.lines[detailIndex];
  return <>
    <Toolbar design="Transparent"><Title level="H2">Authored estimate lines</Title><ToolbarSpacer /><Button disabled={disabled || draft.lines.length >= 100} onClick={() => { const source = choices[0]; const unit = units.find(value => value.id === source?.unitId) || units[0]; onChange({ ...draft, lines: [...draft.lines, emptyLine(unit, source)] }); }}>Add line</Button><Button disabled={disabled} onClick={() => setPasteOpen(true)}>Paste rows</Button></Toolbar>
    <p className="estimate-editor-hint">Manual quantities · Tab between fields · Source revisions stay fixed until you choose a successor. Extensions below are from the last saved calculation.</p>
    {errors.lines && <MessageStrip design="Negative" hideCloseButton>{errors.lines}</MessageStrip>}
    <Table accessibleName="Editable estimate lines" overflowMode="Scroll" headerRow={<TableHeaderRow><TableHeaderCell width="3rem">#</TableHeaderCell><TableHeaderCell width="24%" minWidth="15rem">Description</TableHeaderCell><TableHeaderCell width="9rem" horizontalAlign="End">Quantity</TableHeaderCell><TableHeaderCell width="8rem">Unit</TableHeaderCell><TableHeaderCell minWidth="14rem">Rate / assembly</TableHeaderCell><TableHeaderCell width="9rem" horizontalAlign="End">Saved extension</TableHeaderCell><TableHeaderCell width="5rem">Details</TableHeaderCell></TableHeaderRow>}>
      {draft.lines.map((line, index) => {
        const sourceId = 'rate_source_id' in line ? line.rate_source_id : line.assembly_revision_id;
        const source = choices.find(value => value.id === sourceId);
        const amount = calculated.find(value => value.line_id === line.line_id)?.extension;
        return <TableRow key={line.line_id} rowKey={line.line_id}><TableCell>{index + 1}</TableCell>
          <TableCell><Input accessibleName={`Line ${index + 1} description`} value={line.description} disabled={disabled} maxlength={200} valueState={errors[`lines.${index}.description`] ? 'Negative' : 'None'} onInput={event => setLine(index, { ...line, description: event.currentTarget!.value })} /></TableCell>
          <TableCell horizontalAlign="End"><Input className="decimal-input" accessibleName={`Line ${index + 1} quantity`} value={line.quantity.amount} disabled={disabled} valueState={errors[`lines.${index}.quantity`] ? 'Negative' : 'None'} onInput={event => setLine(index, { ...line, quantity: { ...line.quantity, amount: event.currentTarget!.value } })} /></TableCell>
          <TableCell><Select accessibleName={`Line ${index + 1} unit`} disabled={disabled} valueState={errors[`lines.${index}.unit`] ? 'Negative' : 'None'} onChange={event => { const unit = units.find(value => value.id === event.detail.selectedOption.value)!; setLine(index, { ...line, quantity: { ...line.quantity, unit_id: unit.id, precision: unit.fields.precision } }); }}><Option value="" selected={!line.quantity.unit_id}>Choose unit</Option>{units.map(unit => <Option key={unit.id} value={unit.id} selected={line.quantity.unit_id === unit.id}>{unit.fields.symbol} · {unit.fields.dimension.replaceAll('_', ' ')}</Option>)}</Select></TableCell>
          <TableCell><div className="source-select-cell"><Select accessibleName={`Line ${index + 1} source`} disabled={disabled} valueState={errors[`lines.${index}.source`] ? 'Negative' : 'None'} onChange={event => { const selected = choices.find(value => value.id === event.detail.selectedOption.value); if (selected) setLine(index, selectLineSource(line, selected)); }}><Option value="" selected={!sourceId}>Choose source</Option>{choices.map(value => <Option key={value.id} value={value.id} selected={sourceId === value.id}>{value.label}</Option>)}</Select>{source && <Button design="Transparent" accessibleName={`Inspect line ${index + 1} source`} onClick={() => onInspect(source.kind, source.id)}>Inspect</Button>}</div></TableCell>
          <TableCell horizontalAlign="End"><span className="exact-number">{amount ? exactDisplay(amount.amount) : '—'}</span></TableCell><TableCell><Button accessibleName={`Line ${index + 1} details`} onClick={() => setDetailId(line.line_id)}>Edit</Button></TableCell>
        </TableRow>;
      })}
    </Table>
    {Object.keys(errors).some(key => key.startsWith('lines.')) && <ul className="estimate-validation" aria-label="Estimate line validation">{Object.entries(errors).filter(([key]) => key.startsWith('lines.')).map(([key, message]) => <li key={key}>Line {Number(key.split('.')[1]) + 1}: {message}</li>)}</ul>}
    {!draft.lines.length && <p className="estimate-editor-hint">Add a line or paste source-linked rows to begin.</p>}
    {pasteOpen && <PasteDialog units={units} choices={choices} available={100 - draft.lines.length} onClose={() => setPasteOpen(false)} onAdd={lines => { onChange({ ...draft, lines: [...draft.lines, ...lines] }); setPasteOpen(false); }} />}
    {detail && <Dialog open headerText={`Line ${detailIndex + 1} details`} className="form-dialog" onClose={() => setDetailId(undefined)} footer={<Bar design="Footer" endContent={<Button onClick={() => setDetailId(undefined)}>Done</Button>} />}><div className="dialog-form"><p>{detail.description || 'Untitled line'}</p><Label>Cost code</Label><Input accessibleName="Line cost code" value={detail.cost_code} disabled={disabled} onInput={event => setLine(detailIndex, { ...detail, cost_code: event.currentTarget!.value })} /><Label>Notes</Label><TextArea accessibleName="Line notes" value={detail.notes} disabled={disabled} onInput={event => setLine(detailIndex, { ...detail, notes: event.currentTarget!.value })} /><Label>Alternate label</Label><Input accessibleName="Line alternate" value={detail.alternate} disabled={disabled} onInput={event => setLine(detailIndex, { ...detail, alternate: event.currentTarget!.value })} /><CheckBox text="Include this line in the estimate" checked={detail.included} disabled={disabled} onChange={event => setLine(detailIndex, { ...detail, included: event.currentTarget!.checked })} />{'material_factor' in detail && <><Label>Material factor</Label><Input accessibleName="Line material factor" value={detail.material_factor} disabled={disabled} onInput={event => setLine(detailIndex, { ...detail, material_factor: event.currentTarget!.value })} /><Label>Waste fraction</Label><Input accessibleName="Line waste fraction" value={detail.waste_fraction} disabled={disabled} onInput={event => setLine(detailIndex, { ...detail, waste_fraction: event.currentTarget!.value })} /><p className="caption">Enter an exact fraction: 0.05 means 5% waste. Source-unit conversions are checked by the server.</p></>}<Button design="Negative" disabled={disabled} onClick={() => { onChange({ ...draft, lines: draft.lines.filter(line => line.line_id !== detail.line_id) }); setDetailId(undefined); }}>Remove line</Button><details><summary>Stable line identity</summary><code className="packet-hash">{detail.line_id}</code></details></div></Dialog>}
  </>;
}

function PasteDialog({ units, choices, available, onClose, onAdd }: { units: EstUnitRecord[]; choices: SourceChoice[]; available: number; onClose: () => void; onAdd: (lines: EstLineInput[]) => void }) {
  const [text, setText] = useState(''); const [error, setError] = useState('');
  return <Dialog open headerText="Paste estimate rows" className="estimate-inspector" onClose={onClose} footer={<Bar design="Footer" endContent={<><Button design="Emphasized" disabled={!text.trim()} onClick={() => { try { const lines = parsePastedLines(text, units, choices); if (lines.length > available) throw new Error(`There is room for ${available} more lines.`); onAdd(lines); } catch (failure) { setError((failure as Error).message); } }}>Add pasted rows</Button><Button onClick={onClose}>Cancel paste</Button></>} />}><div className="dialog-form"><p>Paste tab-separated cells from a spreadsheet. All rows are validated before they are added.</p><p className="caption">Columns: Description · Quantity · Unit name or ID · Rate/assembly title or ID · Cost code (optional) · Waste fraction (optional, direct rates).</p>{error && <MessageStrip design="Negative" hideCloseButton>{error}</MessageStrip>}<TextArea accessibleName="Tab-separated estimate rows" rows={9} value={text} onInput={event => { setText(event.currentTarget!.value); setError(''); }} /><p className="caption">Quantities and fractions stay exact text. No calculation is saved by pasting.</p></div></Dialog>;
