function NewEstimate({ company, project, onClose, onCreated }: { company: string; project: string; onClose: () => void; onCreated: (id: string) => void }) {
  const [title, setTitle] = useState(''); const [currency, setCurrency] = useState(''); const [pricingDate, setPricingDate] = useState(new Date().toISOString().slice(0, 10));
  const [operationId, setOperationId] = useState(() => crypto.randomUUID()); const [saving, setSaving] = useState(false); const [error, setError] = useState<ApiError>();
  const change = () => { setOperationId(crypto.randomUUID()); setError(undefined); };
  const submit = async () => { setSaving(true); setError(undefined); try { const response = await estimating.create({ company, project, title: title.trim(), currency, pricing_date: pricingDate, operation_id: operationId }); onCreated(response.estimate.id); } catch (failure) { setError(failure as ApiError); } finally { setSaving(false); } };
  return <Dialog open headerText="Create estimate draft" className="form-dialog" onClose={() => { if (!saving) onClose(); }} footer={<Bar design="Footer" endContent={<><Button design="Emphasized" disabled={saving || !title.trim() || !/^[A-Z]{3}$/.test(currency) || !/^\d{4}-\d{2}-\d{2}$/.test(pricingDate)} onClick={submit}>{saving ? 'Creating…' : 'Create draft'}</Button><Button disabled={saving} onClick={onClose}>Cancel</Button></>} />}><div className="dialog-form">{error && <Failure error={error} />}<Label required>Estimate title</Label><Input accessibleName="Estimate title" value={title} maxlength={200} disabled={saving} onInput={event => { setTitle(event.currentTarget!.value); change(); }} /><Label required>Currency</Label><Input accessibleName="Estimate currency" placeholder="Three-letter code, e.g. USD" value={currency} maxlength={3} disabled={saving} onInput={event => { setCurrency(event.currentTarget!.value.toUpperCase()); change(); }} /><Label required>Pricing date</Label><Input accessibleName="Estimate pricing date" placeholder="YYYY-MM-DD" value={pricingDate} disabled={saving} onInput={event => { setPricingDate(event.currentTarget!.value); change(); }} /><p className="caption">Currency must be enabled in your ERP workspace. No company currency is assumed.</p></div></Dialog>;
}

function EstimateDetail({ company, project, estimateId, revisionId, navigate, askRicky }: { company: string; project: Project; estimateId: string; revisionId?: string; navigate: (path: string) => void; askRicky: () => void }) {
  const scope = `${company}/${project.id}/${estimateId}`;
  const view = useResource(`${scope}/${revisionId || 'head'}`, signal => loadEstimate(company, project.id, estimateId, signal, revisionId));
  const units = useResource(`${company}/${project.id}/units`, signal => estimating.units(company, project.id, signal));
  const rates = useEstimateLibrary(company, project.id, 'rate'); const assemblies = useEstimateLibrary(company, project.id, 'assembly'); const conversions = useEstimateLibrary(company, project.id, 'conversion');
  const [draft, setDraft] = useState<EstimateDraft>(); const [baseRevision, setBaseRevision] = useState<string | null>(null); const [baseSnapshot, setBaseSnapshot] = useState<EstSnapshotRecord>();
  const [dirty, setDirty] = useState(false); const [saving, setSaving] = useState(false); const [unknown, setUnknown] = useState(false); const [conflict, setConflict] = useState(false); const [rebasedReview, setRebasedReview] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({}); const [serverError, setServerError] = useState<ApiError>(); const [notice, setNotice] = useState(''); const [operationId, setOperationId] = useState(() => crypto.randomUUID());
  const pending = useRef<(CalculateRevisionRequest & { operation_id: string }) | undefined>(undefined);
  const [inspection, setInspection] = useState<{ kind: 'rate' | 'assembly' | 'snapshot'; id: string }>(); const [citation, setCitation] = useState<EstCitation>();
  const [compare, setCompare] = useState(false);
  const predecessor = useResource(compare && view.data?.revision?.predecessor ? `${scope}/predecessor/${view.data.revision.predecessor}` : null, signal => loadEstimate(company, project.id, estimateId, signal, view.data!.revision!.predecessor!));
  useEffect(() => { if (view.data && !draft) { setDraft(draftFromSnapshot(view.data.snapshot)); setBaseRevision(view.data.revision?.id || null); setBaseSnapshot(view.data.snapshot); } }, [view.data, draft]);
  useEffect(() => { if (!dirty) return; const prevent = (event: BeforeUnloadEvent) => { event.preventDefault(); }; window.addEventListener('beforeunload', prevent); return () => window.removeEventListener('beforeunload', prevent); }, [dirty]);
  const choices = useMemo<SourceChoice[]>(() => {
    const all = new Map<string, SourceChoice>();
    for (const source of Object.values(baseSnapshot?.inputs.rates || {})) all.set(source.id, { id: source.id, kind: 'rate', label: `${source.title} · Rate rev. ${source.revision}`, unitId: source.unit_id, rate: source });
    for (const source of Object.values(baseSnapshot?.inputs.assemblies || {})) all.set(source.id, { id: source.id, kind: 'assembly', label: `${source.title} · Assembly rev. ${source.revision}`, unitId: source.basis_unit_id, assembly: source });
    for (const record of rates.items) all.set(record.id, { id: record.id, kind: 'rate', label: `${record.rate.title} · Rate rev. ${record.rate.revision}`, unitId: record.rate.unit_id, rate: record.rate });
    for (const record of assemblies.items) all.set(record.id, { id: record.id, kind: 'assembly', label: `${record.assembly.title} · Assembly rev. ${record.assembly.revision}`, unitId: record.assembly.basis_unit_id, assembly: record.assembly });
    return [...all.values()];
  }, [baseSnapshot, rates.items, assemblies.items]);
  const edit = (next: EstimateDraft) => { if (unknown || saving) return; setDraft(next); setDirty(true); setOperationId(crypto.randomUUID()); pending.current = undefined; setErrors({}); setServerError(undefined); setNotice(''); };
  const canEdit = !revisionId && Boolean(project.capabilities?.includes('estimate.write') && project.capabilities?.includes('document.read'));
  const calculate = async () => {
    if (!draft || saving || !view.data) return;
    if (!unknown) { const validation = validateDraft(draft, units.data?.items || [], choices); setErrors(validation); if (Object.keys(validation).length) return; }
    setSaving(true); setServerError(undefined); setNotice('');
    if (!pending.current) pending.current = { company, project: project.id, operation_id: operationId, estimate_id: estimateId, expected_revision: baseRevision, lines: structuredClone(draft.lines), adjustments: structuredClone(draft.adjustments), conversion_ids: [...draft.conversion_ids], basis_description: draft.basis_description, basis_citations: draft.basis_citations.map(({ revision_id, page, excerpt_sha256, source_sha256 }) => ({ revision_id, page, excerpt_sha256, source_sha256 })) as CalculateRevisionRequest['basis_citations'] };
    try {
      const result = await estimating.calculate(pending.current);
      setDraft(draftFromSnapshot(result.calculation)); setBaseRevision(result.revision.id); setBaseSnapshot(result.calculation); setDirty(false); setUnknown(false); setConflict(false); setOperationId(crypto.randomUUID()); pending.current = undefined; view.refresh(); setNotice(`Revision ${result.revision.revision_number} saved${result.operation.replayed ? ' · Original operation recovered' : ''}.`);
    } catch (failure) {
      const problem = failure as ApiError; setServerError(problem);
      if (!problem.status || problem.status >= 500) setUnknown(true);
      else { setUnknown(false); pending.current = undefined; if (problem.status === 412) setConflict(true); if (problem.status === 422 && typeof problem.details?.field === 'string') { const field = problem.details.field.replace(/^inputs\./, '').replace(/\[(\d+)\]/g, '.$1').replace(/\.quantity\.unit_id$/, '.unit').replace(/\.quantity\..*$/, '.quantity').replace(/\.(?:rate_source_id|assembly_revision_id)$/, '.source'); setErrors({ [field]: problem.message }); } if ([403, 404].includes(problem.status)) view.refresh(); }
    } finally { setSaving(false); }
  };
  if (view.loading && !view.data) return <Loading label="Loading estimate and exact saved calculation…" />;
  if (view.error) return <div className="page"><Failure error={view.error} onRetry={view.refresh} /></div>;
  if (!view.data || !draft) return <Loading label="Preparing estimate draft…" />;
  const current = view.data; const latestId = current.estimate.current_revision;
  const staleLoaded = conflict && latestId !== baseRevision;
  const disabled = !canEdit || saving || unknown;
  return <>
    <ObjectPage className="project-object-page estimate-object-page" titleArea={<ObjectPageTitle header={<h1>{current.estimate.title}</h1>} subHeader={<span className="caption">{project.name} · {current.estimate.currency} · Pricing {date(current.estimate.pricing_date)}</span>} breadcrumbs={<Breadcrumbs><BreadcrumbsItem onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}/estimates`)}>Estimates</BreadcrumbsItem><BreadcrumbsItem>{current.estimate.title}</BreadcrumbsItem></Breadcrumbs>} actionsBar={<Toolbar design="Transparent"><ToolbarButton text="Ask Ricky" icon="da" onClick={askRicky} />{canEdit && <ToolbarButton text={saving ? 'Calculating…' : unknown ? 'Recover calculation' : 'Calculate & save revision'} design="Emphasized" disabled={saving || conflict || units.loading || !units.data} onClick={calculate} />}</Toolbar>}><Status value={dirty ? 'Unsaved changes' : current.revision ? 'Calculated draft' : 'Draft'} /></ObjectPageTitle>} headerArea={<ObjectPageHeader><div className="project-facts"><Fact label="Saved revision">{current.revision ? `Rev. ${current.revision.revision_number}` : 'Not calculated'}</Fact><Fact label="Saved direct cost">{current.snapshot ? exactDisplay(current.snapshot.result.direct.amount) : '—'}</Fact><Fact label="Saved total">{current.snapshot ? `${current.estimate.currency} ${exactDisplay(current.snapshot.result.total.amount)}` : '—'}</Fact><Fact label="Quantity basis">Authored / manual</Fact></div></ObjectPageHeader>}>
      <ObjectPageSection id="estimate-lines" titleText="Estimate lines"><div className="section-body estimate-editor-surface">
        {notice && <MessageStrip design="Positive" onClose={() => setNotice('')}>{notice}</MessageStrip>}{serverError && <Failure error={serverError} />}
        {unknown && <MessageStrip design="Critical" hideCloseButton>The calculation result is unknown. Recover the original operation before editing; this will not create a duplicate revision.</MessageStrip>}
        {conflict && <div className="estimate-conflict"><MessageStrip design="Critical" hideCloseButton>Your local inputs are preserved. The estimate head changed. Load and review the latest saved revision before rebasing these inputs.</MessageStrip><Button onClick={() => { setRebasedReview(false); view.refresh(); }}>Load latest for comparison</Button>{staleLoaded && <><p>Latest saved revision: {current.revision?.revision_number}. Your inputs still use the original source revision.</p>{baseSnapshot && current.snapshot && <EstimateComparison before={baseSnapshot} after={current.snapshot} beforeLabel="Original saved base" afterLabel="Latest saved head" />}<CheckBox text="I reviewed the latest saved revision changes" checked={rebasedReview} onChange={event => setRebasedReview(event.currentTarget!.checked)} /><Button disabled={!rebasedReview} onClick={() => { setBaseRevision(latestId); setBaseSnapshot(current.snapshot); setConflict(false); setOperationId(crypto.randomUUID()); setServerError(undefined); setNotice('Your inputs are preserved and rebased. Calculate again to save a new revision.'); }}>Rebase preserved inputs</Button></>}</div>}
        {revisionId && <MessageStrip design="Information" hideCloseButton>This is an immutable saved revision. <Link onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}/estimates/${estimateId}`)}>Open the current draft</Link></MessageStrip>}
        {units.error ? <Failure error={units.error} onRetry={units.refresh} /> : <EstimateLineEditor draft={draft} units={units.data?.items || []} choices={choices} calculated={baseSnapshot?.result.lines || []} errors={errors} disabled={disabled} onChange={edit} onInspect={(kind, id) => setInspection({ kind, id })} />}
        <div className="estimate-basis"><Label required>Estimate basis</Label><TextArea accessibleName="Estimate basis" rows={3} value={draft.basis_description} disabled={disabled} valueState={errors.basis_description ? 'Negative' : 'None'} onInput={event => edit({ ...draft, basis_description: event.currentTarget!.value })} />{errors.basis_description && <p className="estimate-field-error">{errors.basis_description}</p>}<p className="caption">Describe the scope and assumptions supporting these manually authored quantities.</p></div>
        <Adjustments draft={draft} disabled={disabled} onChange={edit} errors={errors} />
        {canEdit && <div className="estimate-save-bar"><span className="caption">{draft.lines.length} lines · {dirty ? 'Local inputs not saved' : 'Inputs match the saved revision'}</span><Button design="Emphasized" disabled={saving || conflict || units.loading || !units.data} onClick={calculate}>{saving ? 'Calculating…' : unknown ? 'Recover calculation' : 'Calculate & save revision'}</Button></div>}
      </div></ObjectPageSection>
      <ObjectPageSection id="estimate-sources" titleText="Sources"><div className="section-body estimate-section-pad"><Title level="H2">Qualified source libraries</Title>{rates.error ? <Failure error={rates.error} onRetry={rates.refresh} /> : assemblies.error ? <Failure error={assemblies.error} onRetry={assemblies.refresh} /> : rates.loading || assemblies.loading ? <Loading label="Loading qualified sources…" /> : <EstimateSourceTables rates={rates.items} assemblies={assemblies.items} onInspect={(kind, id) => setInspection({ kind, id })} />}{rates.next && <Button disabled={rates.loadingMore} onClick={rates.loadMore}>Load more rate sources</Button>}{assemblies.next && <Button disabled={assemblies.loadingMore} onClick={assemblies.loadMore}>Load more assemblies</Button>}{rates.moreError && <Failure error={rates.moreError} />}{assemblies.moreError && <Failure error={assemblies.moreError} />}<details className="estimate-conversions"><summary>Exact conversion revisions ({conversions.items.length})</summary>{conversions.error ? <Failure error={conversions.error} onRetry={conversions.refresh} /> : conversions.items.map(conversion => <CheckBox key={conversion.id} disabled={disabled} text={`${conversion.definition.source}: ${conversion.definition.numerator}/${conversion.definition.denominator}`} checked={draft.conversion_ids.includes(conversion.id)} onChange={event => edit({ ...draft, conversion_ids: event.currentTarget!.checked ? [...new Set([...draft.conversion_ids, conversion.id])] : draft.conversion_ids.filter(id => id !== conversion.id) })} />)}{conversions.next && <Button disabled={conversions.loadingMore} onClick={conversions.loadMore}>Load more conversions</Button>}</details><CitationList citations={baseSnapshot?.source_citations || []} onSource={setCitation} /></div></ObjectPageSection>
      <ObjectPageSection id="estimate-comparison" titleText="Revision comparison"><div className="section-body estimate-section-pad"><Title level="H2">Saved revision comparison</Title>{current.revision?.predecessor ? <><Button onClick={() => setCompare(true)}>Compare with predecessor</Button><Link onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}/estimates/${estimateId}?revision=${current.revision!.predecessor}`)}>Open predecessor revision</Link>{predecessor.loading ? <Loading label="Loading saved predecessor…" /> : predecessor.error ? <Failure error={predecessor.error} onRetry={predecessor.refresh} /> : predecessor.data?.snapshot && current.snapshot && <EstimateComparison before={predecessor.data.snapshot} after={current.snapshot} beforeLabel={`Revision ${predecessor.data.revision!.revision_number}`} afterLabel={`Revision ${current.revision.revision_number}`} />}</> : <Empty title="No predecessor revision" icon="history">Save a successor calculation to compare revisions by stable line identity.</Empty>}</div></ObjectPageSection>
      <ObjectPageSection id="estimate-calculation" titleText="Saved calculation"><div className="section-body estimate-section-pad">{current.snapshot ? <><SnapshotFacts snapshot={current.snapshot} /><Button onClick={() => setInspection({ kind: 'snapshot', id: current.snapshot!.id })}>Inspect calculation snapshot</Button><div className="estimate-totals"><Fact label="Direct">{exactDisplay(current.snapshot.result.direct.amount)}</Fact><Fact label="Indirect">{exactDisplay(current.snapshot.result.indirect.amount)}</Fact><Fact label="Contingency">{exactDisplay(current.snapshot.result.contingency.amount)}</Fact><Fact label="Total">{current.estimate.currency} {exactDisplay(current.snapshot.result.total.amount)}</Fact></div></> : <Empty title="No saved calculation" icon="document-text">Enter source-linked lines and calculate a draft revision.</Empty>}</div></ObjectPageSection>
    </ObjectPage>
    {inspection && <EstimateSourceInspector company={company} project={project.id} kind={inspection.kind} id={inspection.id} onClose={() => setInspection(undefined)} onSource={setCitation} />}
    {citation && <EstimateSourcePreview company={company} citation={citation} onClose={() => setCitation(undefined)} />}
  </>;
}

function Adjustments({ draft, disabled, onChange, errors }: { draft: EstimateDraft; disabled: boolean; onChange: (draft: EstimateDraft) => void; errors: Record<string, string> }) {
  const update = (index: number, adjustment: EstAdjustment) => onChange({ ...draft, adjustments: draft.adjustments.map((value, row) => row === index ? adjustment : value) });
  return <details className="estimate-adjustments"><summary>Indirect cost and contingency ({draft.adjustments.length})</summary><p className="caption">Fractions apply to direct cost; 0.05 means 5%. All resulting amounts come from the server calculation.</p>{draft.adjustments.map((adjustment, index) => <div className="adjustment-form" key={adjustment.line_id}><Input accessibleName={`Adjustment ${index + 1} label`} placeholder="Label" value={adjustment.label} disabled={disabled} onInput={event => update(index, { ...adjustment, label: event.currentTarget!.value })} /><Select accessibleName={`Adjustment ${index + 1} kind`} disabled={disabled} onChange={event => update(index, { ...adjustment, kind: event.detail.selectedOption.value as EstAdjustment['kind'] })}><Option value="indirect" selected={adjustment.kind === 'indirect'}>Indirect</Option><Option value="contingency" selected={adjustment.kind === 'contingency'}>Contingency</Option></Select><Select accessibleName={`Adjustment ${index + 1} method`} disabled={disabled} onChange={event => update(index, { ...adjustment, method: event.detail.selectedOption.value as EstAdjustment['method'] })}><Option value="fixed" selected={adjustment.method === 'fixed'}>Fixed amount</Option><Option value="fraction_of_direct" selected={adjustment.method === 'fraction_of_direct'}>Fraction of direct</Option></Select><Input accessibleName={`Adjustment ${index + 1} value`} value={adjustment.value} disabled={disabled} placeholder="Exact value" onInput={event => update(index, { ...adjustment, value: event.currentTarget!.value })} /><Input accessibleName={`Adjustment ${index + 1} basis`} value={adjustment.basis_description} disabled={disabled} placeholder="Basis" onInput={event => update(index, { ...adjustment, basis_description: event.currentTarget!.value })} /><Button disabled={disabled} accessibleName={`Remove adjustment ${index + 1}`} onClick={() => onChange({ ...draft, adjustments: draft.adjustments.filter((_, row) => row !== index) })}>Remove</Button>{errors[`adjustments.${index}`] && <p className="estimate-field-error">{errors[`adjustments.${index}`]}</p>}</div>)}<Button disabled={disabled || draft.adjustments.length >= 30} onClick={() => onChange({ ...draft, adjustments: [...draft.adjustments, { line_id: crypto.randomUUID(), kind: 'indirect', label: '', method: 'fixed', value: '', basis_description: '' }] })}>Add adjustment</Button></details>;
}

import { useEffect, useRef, useState } from 'react';
import { Avatar, Bar, Button, Dialog, Icon, Link, MessageStrip, NavigationLayout, Option, Select, ShellBar, ShellBarBranding, ShellBarSearch, ShellBarSpacer, SideNavigation, SideNavigationItem, Tag, Title, ToggleButton, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import type { NavigationLayoutDomRef } from '@ui5/webcomponents-react';
import NavigationLayoutMode from '@ui5/webcomponents-fiori/dist/types/NavigationLayoutMode.js';
import { api, ApiError, rpc } from './api/client';
import type { ModelStatus, Project, Session } from './api/types';
import { useResource, useRoute } from './hooks';
import { Empty, Failure, Loading, PageHeading, Status } from './components';
import ProjectRegister from './ProjectRegister';
import ProjectDetail from './ProjectDetail';
import { DocumentPage, DocumentsPage } from './Documents';
import RickyPanel from './RickyPanel';
import SignIn from './SignIn';
import Approvals from './Approvals';
import Estimates from './Estimates';

export default function App() {
  const { path, navigate } = useRoute();
  const session = useResource('session', signal => api.session(signal));
  const [company, setCompany] = useState('');
  const [projectId, setProjectId] = useState('');
  const [rickyOpen, setRickyOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [mode, setMode] = useState<NavigationLayoutMode>(NavigationLayoutMode.Auto);
  const [search, setSearch] = useState('');
  const [dataRevision, setDataRevision] = useState(0);
  const [authRequested, setAuthRequested] = useState(false);
  const [signingOut, setSigningOut] = useState(false);
  const [profileError, setProfileError] = useState<ApiError>();
  const [projectCursor, setProjectCursor] = useState<string>();
  const [projectPages, setProjectPages] = useState<(string | undefined)[]>([]);
  const layoutRef = useRef<NavigationLayoutDomRef>(null);
  const identity = session.data?.person.id ?? '';
  const projects = useResource(company && identity ? `projects/${identity}/${company}/${projectCursor ?? ''}` : null, signal => api.projects(company, signal, projectCursor));
  const route = path.split('?')[0].split('/').filter(Boolean).map(segment => { try { return decodeURIComponent(segment); } catch { return segment; } });
  const citedPage = Number(new URLSearchParams(path.split('?')[1] ?? '').get('page'));
  const routeProjectId = route[0] === 'projects' ? route[1] : undefined;
  const contextId = routeProjectId || projectId;
  const contextProject = useResource(company && contextId && identity ? `project-context/${identity}/${company}/${contextId}` : null, signal => api.project(company, contextId!, signal));
  const selectedProject = contextProject.data ?? projects.data?.items.find(project => project.id === contextId);

  useEffect(() => {
    const currentSession = session.data;
    if (currentSession) setCompany(current => currentSession.companies.some(item => item.id === current) ? current : currentSession.companies[0]?.id ?? '');
  }, [session.data]);
  useEffect(() => { setProjectId(''); setProjectCursor(undefined); setProjectPages([]); setRickyOpen(false); }, [session.data?.user]);
  useEffect(() => {
    const signIn = () => { setAuthRequested(true); setRickyOpen(false); };
    const expired = () => { setAuthRequested(true); setRickyOpen(false); setProfileOpen(false); setProjectId(''); };
    window.addEventListener('cipher:sign-in', signIn); window.addEventListener('cipher:session-expired', expired);
    return () => { window.removeEventListener('cipher:sign-in', signIn); window.removeEventListener('cipher:session-expired', expired); };
  }, []);
  useEffect(() => { if (routeProjectId) setProjectId(routeProjectId); }, [routeProjectId]);
  useEffect(() => { document.title = `${selectedProject?.name ?? (route[0] === 'documents' ? 'Document' : route[0] === 'connections' ? 'Connections' : 'Projects')} · Cipher`; }, [selectedProject?.name, path]);

  const changeCompany = (next: string) => { setCompany(next); setProjectId(''); setSearch(''); setProjectCursor(undefined); setProjectPages([]); navigate('/projects'); };
  const refresh = () => { projects.refresh(); contextProject.refresh(); setDataRevision(value => value + 1); };
  const toggleNavigation = () => setMode(layoutRef.current?.isSideCollapsed() ? NavigationLayoutMode.Expanded : NavigationLayoutMode.Collapsed);
  const documentsPath = selectedProject ? `/projects/${encodeURIComponent(selectedProject.id)}/documents` : '/documents';
  const shellSession = !authRequested && !session.error && session.data?.authenticated ? session.data : undefined;
  const personName = shellSession?.person.display_name ?? 'Workspace session';
  const navKey = route[0] === 'estimates' || route[2] === 'estimates' ? 'estimates' : route[0] === 'documents' || route[2] === 'documents' ? 'documents' : route[0] === 'work' ? 'work' : route[0] === 'connections' ? 'connections' : 'projects';
  return <>
    <a className="skip-link" href="#main-content">Skip to content</a>
    <NavigationLayout ref={layoutRef} id="cipher-navigation" mode={mode} className="product-layout"
      header={<ShellBar id="cipher-shellbar" startButton={<Button icon="menu2" design="Transparent" accessibleName="Toggle navigation" onClick={toggleNavigation} />}
        branding={<ShellBarBranding logo={<img src="/cipher-mark.svg" alt="" />} onClick={() => navigate('/projects')}>Cipher <span className="shell-product-subtitle">The AEC/CMS Pro</span></ShellBarBranding>}
        content={<><div className="company-switch">{shellSession?.companies.length ? <Select accessibleName="Company" valueState="None" onChange={event => changeCompany(event.detail.selectedOption.value ?? company)}>{shellSession.companies.map(item => <Option key={item.id} value={item.id} selected={company === item.id}>{item.name}</Option>)}</Select> : null}</div><ShellBarSpacer />{shellSession?.site_mode === 'synthetic' && <Tag design="Set2" colorScheme="7">Synthetic workspace</Tag>}</>}
        searchField={<ShellBarSearch placeholder="Find a project" accessibleName="Search projects" onSearch={event => { setSearch(event.currentTarget!.value); navigate('/projects'); }} />}
        assistant={<ToggleButton icon="da" pressed={rickyOpen} accessibleName="Toggle Ricky assistant" tooltip="Ricky · AEC intelligence" onClick={() => setRickyOpen(value => !value)} />}
        profile={<Avatar initials={initials(personName)} accessibleName={personName} size="XS" />} onProfileClick={() => { if (shellSession) setProfileOpen(true); }} />}
      sideContent={<SideNavigation className="product-navigation" accessibleName="Cipher workspace navigation" onSelectionChange={event => { const next = event.detail.item.dataset.path; if (next) navigate(next); }} fixedItems={<SideNavigationItem text="Connections" icon="connected" selected={navKey === 'connections'} data-path="/connections" />}>
        <SideNavigationItem text="Projects" icon="building" selected={navKey === 'projects'} data-path="/projects" />
        <SideNavigationItem text="Project work" icon="task" selected={navKey === 'work'} data-path="/work" />
        <SideNavigationItem text="Estimates" icon="simulate" selected={navKey === 'estimates'} data-path={selectedProject ? `/projects/${encodeURIComponent(selectedProject.id)}/estimates` : '/estimates'} />
        <SideNavigationItem text="Documents" icon="documents" selected={navKey === 'documents'} data-path={documentsPath} />
        <SideNavigationItem text="Ricky" icon="da" design="Action" unselectable onClick={() => setRickyOpen(true)} />
      </SideNavigation>}>
      <div className={`workspace-frame${rickyOpen ? ' with-assistant' : ''}`}>
        <div className="workspace-main" id="main-content" tabIndex={-1}>
          {session.loading ? <Loading label="Connecting to your workspace…" /> : authRequested || session.error?.status === 401 || (!session.error && !session.data?.authenticated) ? <SignIn onSignedIn={() => { setAuthRequested(false); session.refresh(); }} /> : session.error ? <WorkspaceUnavailable error={session.error} retry={session.refresh} /> : !session.data?.companies.length ? <div className="page"><Empty title="No company access" icon="locked">Your workspace administrator can assign company and project access.</Empty></div> : <>
            <div className="workspace-context-bar"><div><Icon name="building" /><span>{companyLabel(session.data, company)}</span>{selectedProject && <><span className="context-separator">/</span><strong>{selectedProject.name}</strong></>}</div><Select accessibleName="Project context" onChange={event => { const id = event.detail.selectedOption.value ?? ''; setProjectId(id); navigate(id ? `/projects/${encodeURIComponent(id)}` : '/projects'); }}><Option value="" selected={!selectedProject}>All projects</Option>{projects.data?.items.map(project => <Option key={project.id} value={project.id} selected={selectedProject?.id === project.id}>{project.name}</Option>)}</Select></div>
            {projects.loading && !projects.data ? <Loading label="Loading permitted projects…" /> : projects.error ? <div className="page"><Failure error={projects.error} onRetry={projects.refresh} /></div> : company && <>
              {route[0] === 'estimates' || route[2] === 'estimates' ? (contextId && contextProject.loading ? <Loading label="Opening estimating project context…" /> : contextId && contextProject.error ? <div className="page"><Failure error={contextProject.error} onRetry={contextProject.refresh} /></div> : <Estimates key={`${company}/${selectedProject?.id}/${route[3] || ''}`} company={company} project={contextProject.data} estimateId={route[3]} revisionId={new URLSearchParams(path.split('?')[1] || '').get('revision') || undefined} navigate={navigate} askRicky={() => setRickyOpen(true)} />)
                : route[0] === 'connections' ? <Connections session={session.data} />
                : route[0] === 'documents' && route[1] ? <DocumentPage key={`${company}/${path}`} company={company} documentId={route[1]} revisionId={route[2] === 'revisions' ? route[3] : undefined} initialPage={Number.isInteger(citedPage) && citedPage > 0 ? citedPage : 1} navigate={navigate} askRicky={id => { setProjectId(id); setRickyOpen(true); }} />
                : route[0] === 'documents' || route[2] === 'documents' ? <DocumentsPage key={`${company}/${selectedProject?.id ?? ''}`} company={company} projectId={selectedProject?.id} projectName={selectedProject?.name} navigate={navigate} canUpload={contextProject.data?.capabilities?.includes('document.write') ?? false} />
                : route[0] === 'work' ? <WorkPage key={`${company}/${selectedProject?.id}/${dataRevision}`} company={company} project={selectedProject} navigate={navigate} onEffect={() => { projects.refresh(); contextProject.refresh(); }} />
                : route[0] === 'projects' && routeProjectId ? <ProjectDetail key={`${company}/${routeProjectId}/${dataRevision}`} company={company} projectId={routeProjectId} navigate={navigate} refreshProjects={projects.refresh} onContext={project => setProjectId(project.id)} openRicky={() => setRickyOpen(true)} />
                : <ProjectRegister company={companyLabel(session.data, company)} projects={projects.data?.items ?? []} total={projects.data?.total ?? undefined} search={search} setSearch={setSearch} navigate={navigate} refresh={projects.refresh} pagination={{ next: projects.data?.next_cursor, page: projectPages.length + 1, previous: Boolean(projectPages.length), onNext: () => { if (projects.data?.next_cursor) { setProjectPages([...projectPages, projectCursor]); setProjectCursor(projects.data.next_cursor); } }, onPrevious: () => { setProjectCursor(projectPages[projectPages.length - 1]); setProjectPages(projectPages.slice(0, -1)); } }} />}
            </>}
          </>}
        </div>
        {rickyOpen && !session.loading && !authRequested && session.data?.authenticated && <RickyPanel key={`${session.data.person.id}/${company}/${selectedProject?.id ?? ''}`} company={company} person={session.data.person.id} project={selectedProject} navigate={navigate} onClose={() => setRickyOpen(false)} onSaved={refresh} />}
      </div>
    </NavigationLayout>
    <Dialog open={profileOpen} headerText="Your workspace session" onClose={() => setProfileOpen(false)} footer={<Bar design="Footer" endContent={<><Button disabled={signingOut} onClick={async () => { setSigningOut(true); setProfileError(undefined); try { await api.signOut(); setProfileOpen(false); setAuthRequested(true); setRickyOpen(false); session.refresh(); } catch (error) { setProfileError(error as ApiError); } finally { setSigningOut(false); } }}>{signingOut ? 'Signing out…' : 'Sign out'}</Button><Button onClick={() => setProfileOpen(false)}>Close</Button></>} />}><div className="dialog-form">{profileError && <Failure error={profileError} />}<div className="profile-summary"><Avatar initials={initials(personName)} /><div><Title level="H3">{personName}</Title><p>{session.data?.user ?? 'Not signed in'}</p></div></div><p>Company and project permissions are supplied by your workspace.</p>{session.data?.site_mode === 'synthetic' && <MessageStrip design="Information" hideCloseButton>This workspace contains synthetic data.</MessageStrip>}</div></Dialog>
  </>;
}

function WorkspaceUnavailable({ error, retry }: { error: import('./api/client').ApiError; retry: () => void }) {
  return <div className="page connection-page"><div className="connection-illustration"><Icon name="disconnected" /></div><PageHeading eyebrow="CIPHER WORKSPACE" title={error.status === 401 ? 'Sign in to continue' : 'Your workspace is unavailable'} description="Your project data is loaded from your authenticated workspace." /><Failure error={error} onRetry={retry} /><p className="caption">This application does not substitute sample records when a connection fails.</p></div>;
}

function WorkPage({ company, project, navigate, onEffect }: { company: string; project?: Project; navigate: (path: string) => void; onEffect: () => void }) {
  const tasks = useResource(project ? `${company}/${project.id}/tasks` : null, signal => api.tasks(company, project!.id, signal));
  return <div className="page"><PageHeading eyebrow="PROJECT DELIVERY" title="Project work" description={project ? `Tasks, approvals and follow-up for ${project.name}.` : 'Choose a project to see its work.'} />
    {!project ? <div className="surface"><Empty title="Choose a project" icon="task" action={<Button design="Emphasized" onClick={() => navigate('/projects')}>Open projects</Button>}>Select a project from the context picker or project register.</Empty></div> : tasks.loading ? <Loading label="Loading tasks…" /> : tasks.error ? <Failure error={tasks.error} onRetry={tasks.refresh} /> : <section className="surface work-list"><Toolbar design="Transparent"><Title level="H2">Project tasks ({tasks.data?.items.length ?? 0})</Title><ToolbarSpacer /><Button onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}`)}>Open project</Button></Toolbar>{tasks.data?.items.length ? tasks.data.items.map(task => <div className="work-item" key={task.id}><Icon name="task" /><div><strong>{task.subject}</strong><p>{task.description || task.id}</p></div><Status value={task.status} /></div>) : <Empty title="No tasks yet" icon="task">Create the first task from your project workspace.</Empty>}</section>}
    {project && <section className="surface work-approvals"><Approvals project={project} onEffect={onEffect} /></section>}
  </div>;
}

function Connections({ session }: { session: Session }) {
  const model = useResource('connections/model', signal => rpc<ModelStatus>('cipher_aec.ricky.api.connection_status', {}, false, signal));
  return <div className="page"><PageHeading eyebrow="WORKSPACE" title="Connections" description="Current availability of the services behind your work." actions={<Button icon="refresh" onClick={model.refresh}>Refresh</Button>} />
    <section className="surface connection-list"><div className="connection-item"><div className="connection-icon"><Icon name="database" /></div><div><h2>ERP workspace</h2><p>Authenticated business records, projects and tasks.</p></div><Status value="Connected" /></div><div className="connection-item"><div className="connection-icon"><Icon name="da" /></div><div><h2>Ricky local model</h2><p>{model.data?.message || 'The existing local model connection.'}</p></div>{model.loading ? <span className="caption">Checking…</span> : <Status value={model.data?.available ? 'Connected' : 'Unavailable'} />}</div>{model.error && <Failure error={model.error} onRetry={model.refresh} />}</section>
    <div className="document-policy"><strong>{session.site_mode === 'synthetic' ? 'Synthetic workspace' : 'Workspace access'}</strong><p>Connected records use your current company and project permissions. Ricky availability does not affect manual project work.</p></div>
  </div>;
}

function initials(name: string) { return name.split(/[\s@.]+/).filter(Boolean).slice(0, 2).map(part => part[0]?.toUpperCase()).join('') || 'C'; }
function companyLabel(session: Session, company: string) { return session.companies.find(item => item.id === company)?.name ?? company; }

import '@ui5/webcomponents-react/dist/Assets.js';
